// 불순: 밖을 바꾸고, 시점에 따라 결과가 달라진다
let total = 0;
function add(x) { total += x; return total; }  // 숨은 입출력

// 순수: 입력만으로 결과, 밖을 안 건드림
function add(a, b) { return a + b; }            // add(2,3)는 항상 5

// 순수 함수의 이점:
//  테스트 = 입력→기대 출력 (setup 불필요)
//  같은 입력 재호출 = 캐싱(메모이제이션) 안전
//  서로 독립 = 병렬 실행 안전

const next = [...items, item];               // push 대신 새 배열
const updated = { ...user, role: 'admin' };  // 직접 수정 대신 새 객체
const removed = items.filter((x) => x.id !== id);  // splice 대신

// 이전 값이 그대로 → 되돌리기 쉬움
// 바뀜 = 참조가 다름 → 얕은 비교로 변경 감지(React)
// 아무도 못 바꿈 → 공유, 동시성 안전

const total = orders
  .filter((o) => o.status === 'paid')   // 결제된 것만 (N→M)
  .map((o) => o.amount)                 // 금액만 (변환)
  .reduce((sum, a) => sum + a, 0);      // 합 (접기 N→1)

// vs 명령형: let total=0; for(...) { if(paid) total+=amount; }
// 함수형 쪽이 "무엇을" 하는지 선언적으로 드러남, 각 단계 순수, 불변

// ✗ 섞임: 계산과 IO 가 한 함수에
async function handle(id) {
  const u = await db.get(id);      // IO
  u.score = u.score * 1.1;         // 계산 (+ 가변)
  await db.save(u);                // IO
}
// ✓ 분리: 순수 코어 + 얇은 셸
function bonus(user) { return { ...user, score: user.score * 1.1 }; } // 순수
async function handle(id) {        // 셸: IO 만
  const u = await db.get(id);
  await db.save(bonus(u));          // 코어는 목 없이 테스트 가능
}
